//! Data-driven audit of ALL 45 Battle Royale ranged weapons (`parity/guns/weapons.md`): equip / fire / ADS-fire / reload montages, ADS profile, muzzle flash system and weapon audio, each from the
//! weapon's OWN Blueprint chain (`fn_animgraph::weapon_assets::BR_WEAPON_ASSETS`, generated by `gen-anim-core` from the WID's `WeaponActorClass` CDOs; montage facts `WEAPON_MONTAGES` from the
//! montage packages) and the generated audio tables (`fn_audio::weapon_events`, generated by `fn-audio/examples/weaponaudio.rs`). Nothing is filled in: a weapon whose data lacks a binding is
//! listed in `KNOWN_DATA_GAPS` and the test pins that list, so a data change or a regression both fail.
#[cfg(test)]
mod tests {
    use crate::{loadout_ads, ClipSourceDir};
    use fn_animgraph::weapon_assets::{WeaponAssets, WeaponMontage, BR_WEAPON_ASSETS, WEAPON_MONTAGES};
    use fn_audio::weapon_events as we;

    /// Weapon class from the Blueprint chain itself (the generic Blueprint every weapon of the class derives from).
    fn class_of(w: &WeaponAssets) -> &'static str {
        for (c, name) in [("pistol", "B_Pistol_Generic"), ("assault", "B_Assault_Generic"), ("shotgun", "B_Shotgun_Generic"), ("sniper", "B_Rifle_Generic"), ("launcher", "B_RocketLauncher_Generic"), ("launcher", "B_GrenadeLauncher_Generic_Athena")] {
            if w.chain.contains(&name) { return c; }
        }
        "other"
    }
    fn montage(path: &str) -> Option<&'static WeaponMontage> { WEAPON_MONTAGES.iter().find(|m| m.path == path) }
    /// A binding the chain sets to a real asset (not absent, not an explicit null).
    fn set(v: &str) -> bool { v.starts_with("/Game/") }

    /// (WID, what the data lacks). Every entry is the data's own answer (property absent or explicitly nulled in the whole Blueprint chain): nothing is substituted.
    const KNOWN_DATA_GAPS: &[(&str, &str)] = &[
    ("WID_Assault_Hydraulic_Drum_Athena_SR_Ore_T03", "reload montage carries no PlayReloadFX notify (0 PlaySound notifies)"),
    ("WID_Launcher_Grenade_Athena_R_Ore_T03", "WeaponFireMontage = not serialized"),
    ("WID_Launcher_Grenade_Athena_R_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Launcher_Grenade_Athena_SR_Ore_T03", "WeaponFireMontage = not serialized"),
    ("WID_Launcher_Grenade_Athena_SR_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Launcher_Grenade_Athena_VR_Ore_T03", "WeaponFireMontage = not serialized"),
    ("WID_Launcher_Grenade_Athena_VR_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Launcher_Rocket_Athena_R_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Launcher_Rocket_Athena_R_Ore_T03", "ReloadSounds[1] = "),
    ("WID_Launcher_Rocket_Athena_R_Ore_T03", "reload montage fires ReloadCartridge but ReloadSounds[1] is not serialized"),
    ("WID_Launcher_Rocket_Athena_SR_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Launcher_Rocket_Athena_SR_Ore_T03", "ReloadSounds[1] = "),
    ("WID_Launcher_Rocket_Athena_SR_Ore_T03", "reload montage fires ReloadCartridge but ReloadSounds[1] is not serialized"),
    ("WID_Launcher_Rocket_Athena_VR_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Launcher_Rocket_Athena_VR_Ore_T03", "ReloadSounds[1] = "),
    ("WID_Launcher_Rocket_Athena_VR_Ore_T03", "reload montage fires ReloadCartridge but ReloadSounds[1] is not serialized"),
    ("WID_Pistol_Gatling_Athena_SR_Ore_T03", "WeaponFireMontage = not serialized"),
    ("WID_Pistol_Gatling_Athena_SR_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Pistol_SixShooter_Athena_C_Ore_T02", "ReloadSounds[1] = <null>"),
    ("WID_Pistol_SixShooter_Athena_C_Ore_T02", "reload montage fires ReloadCartridge but ReloadSounds[1] is <null>"),
    ("WID_Pistol_SixShooter_Athena_R_Ore_T03", "ReloadSounds[1] = <null>"),
    ("WID_Pistol_SixShooter_Athena_R_Ore_T03", "reload montage fires ReloadCartridge but ReloadSounds[1] is <null>"),
    ("WID_Pistol_SixShooter_Athena_UC_Ore_T03", "ReloadSounds[1] = <null>"),
    ("WID_Pistol_SixShooter_Athena_UC_Ore_T03", "reload montage fires ReloadCartridge but ReloadSounds[1] is <null>"),
    ("WID_Pistol_Zapper_Athena_SR_Ore_T03", "WeaponFireMontage = not serialized"),
    ("WID_Pistol_Zapper_Athena_SR_Ore_T03", "WeaponFireDownsightsMontage = not serialized"),
    ("WID_Pistol_Zapper_Athena_SR_Ore_T03", "WeaponReloadMontage = not serialized"),
    ("WID_Sniper_AMR_Athena_SR_Ore_T03", "WeaponFireMontage = <null>"),
    ("WID_Sniper_AMR_Athena_SR_Ore_T03", "WeaponFireDownsightsMontage = <null>"),
    ];

    fn gaps() -> Vec<(String, String)> {
        let mut g = vec![];
        for w in BR_WEAPON_ASSETS {
            let mut lack = |what: &str| g.push((w.wid.to_string(), what.to_string()));
            for (role, v) in [("EquipAnimation", w.equip), ("FireAnimation", w.fire), ("FireDownsightsAnimation", w.fire_ads), ("ReloadAnimation", w.reload), ("WeaponFireMontage", w.w_fire), ("WeaponFireDownsightsMontage", w.w_fire_ads), ("WeaponReloadMontage", w.w_reload)] {
                if !set(v) { lack(&format!("{role} = {}", if v.is_empty() { "not serialized" } else { v })); }
            }
            if !set(w.muzzle_system) { lack("MuzzleParticleSystem"); }
            for (i, n) in ["PrimaryFireSound", "PrimaryFireSound[1] (low ammo)", "PrimaryFireSound[2] (degraded)"].iter().enumerate() { if !set(w.fire_sound[i]) { lack(&format!("{n} = {}", w.fire_sound[i])); } }
            if !set(w.out_of_ammo) { lack("OutOfAmmoSound"); }
            for (i, n) in ["ReloadSounds[0]", "ReloadSounds[1]", "ReloadSounds[2]"].iter().enumerate() { if !set(w.reload_sound[i]) { lack(&format!("{n} = {}", w.reload_sound[i])); } }
            if !set(w.camera_base) || !set(w.camera_targeting) { lack("ADS camera class"); }
            // equip montage: AnimNotify_PlaySound (the equip sound); reload montage: AnimNotify_PlayReloadFX stages (the reload sounds)
            if let Some(m) = montage(w.equip) { if m.sounds.is_empty() { lack("equip montage carries no PlaySound notify"); } }
            if let Some(m) = montage(w.reload) { if m.reload_fx.is_empty() { lack(&format!("reload montage carries no PlayReloadFX notify ({} PlaySound notifies)", m.sounds.len())); } }
            // the reload montage fires PlayReloadFX(stage) -> ReloadSounds[stage] (exe vfunc_256 RVA 0x935350): a stage whose sound the data leaves unset is silent
            if set(w.reload) {
                for st in montage(w.reload).map_or(&[][..], |m| m.reload_fx) {
                    let i = match *st { "ReloadStart" => 0, "ReloadCartridge" => 1, _ => 2 };
                    if !set(w.reload_sound[i]) { lack(&format!("reload montage fires {st} but ReloadSounds[{i}] is {}", if w.reload_sound[i].is_empty() { "not serialized" } else { w.reload_sound[i] })); }
                }
            }
        }
        g
    }

    #[test]
    fn all_45_br_weapons_are_in_the_generated_table_with_their_class() {
        assert_eq!(BR_WEAPON_ASSETS.len(), 45);
        let mut counts = std::collections::BTreeMap::<&str, usize>::new();
        for w in BR_WEAPON_ASSETS { assert_ne!(class_of(w), "other", "{}: chain {:?}", w.wid, w.chain); *counts.entry(class_of(w)).or_default() += 1; }
        eprintln!("class counts {counts:?}");
        // every WID resolves to a Blueprint the audio tables know
        for w in BR_WEAPON_ASSETS { assert!(we::bp_known(w.actor), "{}: {} not in weapon_bp_table::BPS", w.wid, w.actor); assert!(we::BPS.iter().any(|(b, ws)| *b == w.actor && ws.contains(&w.wid)), "{} not listed under {}", w.wid, w.actor); }
    }

    #[test]
    fn every_weapon_has_the_montages_sounds_and_muzzle_its_class_implies_or_is_a_listed_data_gap() {
        let g = gaps();
        for (w, what) in &g { eprintln!("GAP {w}: {what}"); }
        let want: Vec<(String, String)> = KNOWN_DATA_GAPS.iter().map(|(a, b)| (a.to_string(), b.to_string())).collect();
        assert_eq!(g, want, "the data gaps changed; update KNOWN_DATA_GAPS only after checking the data");
    }

    #[test]
    fn montages_load_and_carry_the_notifies_their_role_implies() {
        for w in BR_WEAPON_ASSETS {
            for (role, v) in [("equip", w.equip), ("fire", w.fire), ("fire_ads", w.fire_ads), ("reload", w.reload), ("w_fire", w.w_fire), ("w_fire_ads", w.w_fire_ads), ("w_reload", w.w_reload)] {
                if !set(v) { continue; }
                let m = montage(v).unwrap_or_else(|| panic!("{} {role}: {v} is not a loadable montage package", w.wid));
                assert!(m.length > 0. && m.segments >= 1, "{} {role} {v}: length {} segments {}", w.wid, m.length, m.segments);
            }
        }
    }

    /// The generated audio tables are the same data as the generated asset table: fire / low-ammo / out-of-ammo / reload cues, persistent-fire mode, and fire loops only for persistent-fire weapons.
    #[test]
    fn audio_rows_agree_with_the_blueprint_chains_and_loops_only_exist_for_persistent_fire() {
        for w in BR_WEAPON_ASSETS {
            let cue = |kind: &str| we::bp_event(w.actor, kind).and_then(we::lookup).map(|c| c.cue.to_string());
            let want = |v: &str| if set(v) { Some(v.to_string()) } else { None };
            assert_eq!(cue("fire"), want(w.fire_sound[0]), "{} fire", w.wid);
            assert_eq!(cue("fire.lowammo"), want(w.fire_sound[1]), "{} low ammo", w.wid);
            assert_eq!(cue("fire.degraded"), want(w.fire_sound[2]), "{} degraded", w.wid);
            assert_eq!(cue("empty"), want(w.out_of_ammo), "{} empty", w.wid);
            for (i, k) in ["reload.start", "reload.cartridge", "reload.end"].iter().enumerate() { assert_eq!(cue(k), want(w.reload_sound[i]), "{} {k}", w.wid); }
            for (i, k) in ["fire.stop", "fire.stop.lowammo", "fire.stop.degraded"].iter().enumerate() { assert_eq!(cue(k), want(w.fire_stop_sound[i]), "{} {k}", w.wid); }
            assert_eq!(we::bp_persistent_fire(w.actor), w.persistent_fire, "{} bPersistentFireFX", w.wid);
            let (_, _, loops) = we::bp_fire_fx(w.actor).unwrap();
            if loops.iter().any(|l| *l) { assert!(w.persistent_fire, "{}: a looping fire cue on a non-persistent weapon", w.wid); }
        }
    }

    /// ADS: every WID resolves to its camera modes (+ scope data for scope weapons) from the install.
    #[test]
    fn every_weapon_has_an_ads_profile() {
        let root = fn_live::var_os("FN_TEST_ROOT").expect("set FN_TEST_ROOT to the local 1.8 install");
        let set_ = fn_pak::PakSet::open_install(root).unwrap();
        let src = ClipSourceDir::Pak(&set_);
        let mut scopes = vec![];
        for w in BR_WEAPON_ASSETS {
            let p = loadout_ads::profile(&src, &format!("/Game/Athena/Items/Weapons/{}", w.wid)).unwrap_or_else(|e| panic!("{}: {e}", w.wid));
            assert!(p.targeting.fov > 0. && p.base.fov > 0., "{}", w.wid);
            assert!(p.base.chain[0].ends_with(w.camera_base.rsplit('/').next().unwrap()) && p.targeting.chain[0].ends_with(w.camera_targeting.rsplit('/').next().unwrap()), "{}: camera classes differ from the generated table", w.wid);
            if p.use_scope { scopes.push(w.wid); assert!(p.scope.is_some()); }
        }
        eprintln!("scope weapons: {scopes:?}");
    }
}
